package com.community.skillersafeground;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("skillersafeground")
public interface SkillerSafeGroundConfig extends Config
{
    @ConfigSection(
        name = "Aggressive NPC Firewall",
        description = "Settings tracking hostile entities and threat perimeters.",
        position = 1
    )
    String npcSection = "npcSection";

    @ConfigItem(
        keyName = "showFirewallTiles",
        name = "Enable Danger Radius",
        description = "Draws red danger grid layouts inside threat bounds.",
        position = 1,
        section = npcSection
    )
    default boolean showFirewallTiles() { return true; }

    @Alpha
    @ConfigItem(
        keyName = "firewallColor",
        name = "Danger Aura Color",
        description = "The color transparency for shaded threat zone tiles.",
        position = 2,
        section = npcSection
    )
    default Color firewallColor() { return new Color(255, 0, 0, 35); }

    @ConfigItem(
        keyName = "trackWizards",
        name = "Track Dark Wizards & Cultists",
        description = "Maps perimeter bounds for Varrock south gate casters and Zamorak monks.",
        position = 3,
        section = npcSection
    )
    default boolean trackWizards() { return true; }

    @ConfigItem(
        keyName = "trackGuards",
        name = "Track Jail Guards & Highwaymen",
        description = "Maps perimeter bounds for Draynor village area hostiles.",
        position = 4,
        section = npcSection
    )
    default boolean trackGuards() { return true; }

    @ConfigItem(
        keyName = "trackScorpions",
        name = "Track All Scorpions",
        description = "Maps perimeter bounds for Al Kharid, Wilderness, and Mine scorpions.",
        position = 5,
        section = npcSection
    )
    default boolean trackScorpions() { return true; }

    @ConfigItem(
        keyName = "trackIceDungeon",
        name = "Track Ice Giants & Warriors",
        description = "Maps lethal bounds inside the Asgarnian Ice Dungeon.",
        position = 6,
        section = npcSection
    )
    default boolean trackIceDungeon() { return true; }

    @ConfigItem(
        keyName = "trackGiantsSpiders",
        name = "Track Giants & Spiders",
        description = "Maps Hill/Moss Giants and Deadly Red Spiders in Sewers and Dungeons.",
        position = 7,
        section = npcSection
    )
    default boolean trackGiantsSpiders() { return true; }

    @ConfigItem(
        keyName = "trackStronghold",
        name = "Track Stronghold of Security",
        description = "Maps Minotaurs, Flesh Crawlers, Catablepons, and Ankous for safe 10k GP runs.",
        position = 8,
        section = npcSection
    )
    default boolean trackStronghold() { return true; }

    @ConfigItem(
        keyName = "trackDeepWildy",
        name = "Track Deep Wilderness Beasts",
        description = "Maps Lesser Demons, Bandits, Chaos Dwarves, Grizzly Bears, and Ghosts.",
        position = 9,
        section = npcSection
    )
    default boolean trackDeepWildy() { return true; }

    @ConfigSection(
        name = "Universal Attack Metronome",
        description = "Visual tick-countdowns synchronized to entity animation speeds.",
        position = 2
    )
    String metronomeSection = "metronomeSection";

    @ConfigItem(
        keyName = "enableGlobalMetronome",
        name = "Enable Overhead Ticks",
        description = "Renders text countdowns above active targets indicating when their next strike will fire.",
        position = 1,
        section = metronomeSection
    )
    default boolean enableGlobalMetronome() { return true; }

    @ConfigItem(
        keyName = "showDistanceHUD",
        name = "Show Distance In Metronome",
        description = "Appends your exact tile distance directly into the overhead text tracker.",
        position = 2,
        section = metronomeSection
    )
    default boolean showDistanceHUD() { return true; }

    @ConfigSection(
        name = "Quest & Skilling Utilities",
        description = "Markers highlighting non-aggressive milestone quest figures.",
        position = 3
    )
    String questSection = "questSection";

    @ConfigItem(
        keyName = "trackQuestNPCs",
        name = "Highlight Quest Targets",
        description = "Highlights vital F2P quest targets (Willow, Checkal, Marley, Ramarno, Aubury).",
        position = 1,
        section = questSection
    )
    default boolean trackQuestNPCs() { return true; }

    @Alpha
    @ConfigItem(
        keyName = "questNpcColor",
        name = "Quest Target Aura",
        description = "The color highlight used to anchor friendly quest lines.",
        position = 2,
        section = questSection
    )
    default Color questNpcColor() { return new Color(0, 191, 255, 45); }

    @ConfigSection(
        name = "Logout Security Dashboard",
        description = "Diagnostic text overlays and customized true-tile colors.",
        position = 4
    )
    String logoutSection = "logoutSection";

    @ConfigItem(
        keyName = "showLogoutPanel",
        name = "Enable Logout Panel",
        description = "Displays the diagnostic top-left HUD state monitor box.",
        position = 1,
        section = logoutSection
    )
    default boolean showLogoutPanel() { return true; }

    @ConfigItem(
        keyName = "showTrueTile",
        name = "Highlight True-Tile",
        description = "Renders your character real server-side ground point.",
        position = 2,
        section = logoutSection
    )
    default boolean showTrueTile() { return true; }

    @Alpha
    @ConfigItem(
        keyName = "safeTileColor",
        name = "Safe State Color",
        description = "The color of your true tile when outside aggro parameters.",
        position = 3,
        section = logoutSection
    )
    default Color safeTileColor() { return new Color(0, 255, 0, 75); }

    @Alpha
    @ConfigItem(
        keyName = "unsafeTileColor",
        name = "Unsafe State Color",
        description = "The color of your true tile when overlapping an enemy boundary grid.",
        position = 4,
        section = logoutSection
    )
    default Color unsafeTileColor() { return new Color(255, 0, 0, 115); }

    @ConfigItem(
        keyName = "panelFontSize",
        name = "Text Size Scale (%)",
        description = "Scales font metrics rendering inside the UI dashboard monitor.",
        position = 5,
        section = logoutSection
    )
    default int panelFontSize() { return 100; }
}

package com.community.skillersafeground;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;

public class SkillerSafeGroundOverlay extends Overlay
{
    private final Client client;
    private final SkillerSafeGroundPlugin plugin;
    private final SkillerSafeGroundConfig config;
    private final PanelComponent panelComponent = new PanelComponent();

    @Inject
    public SkillerSafeGroundOverlay(Client client, SkillerSafeGroundPlugin plugin, SkillerSafeGroundConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        panelComponent.getChildren().clear();
        if (client.getLocalPlayer() == null) return null;

        WorldPoint playerLoc = client.getLocalPlayer().getWorldLocation();
        boolean isCurrentlySafe = true;

        // LAYER 1: Threat Firewalls
        for (NPC npc : plugin.getDangerousNpcs())
        {
            WorldPoint npcLoc = npc.getWorldLocation();
            if (npcLoc == null) continue;

            int distance = playerLoc.distanceTo(npcLoc);
            if (distance <= 5)
            {
                isCurrentlySafe = false;
            }

            if (config.showFirewallTiles())
            {
                int radius = 5;
                for (int dx = -radius; dx <= radius; dx++)
                {
                    for (int dy = -radius; dy <= radius; dy++)
                    {
                        WorldPoint targetTile = new WorldPoint(npcLoc.getX() + dx, npcLoc.getY() + dy, npcLoc.getPlane());
                        LocalPoint lp = LocalPoint.fromWorld(client, targetTile);
                        if (lp != null)
                        {
                            java.awt.Polygon poly = Perspective.getCanvasTilePoly(client, lp);
                            if (poly != null)
                            {
                                graphics.setColor(config.firewallColor());
                                graphics.fillPolygon(poly);
                            }
                        }
                    }
                }
            }

            // Universal Overhead Metronome Calculation Engine
            if (config.enableGlobalMetronome())
            {
                int currentTicks = plugin.getNpcMetronomeTimers().getOrDefault(npc, 4);
                String displayString = "ATTACK IN: " + currentTicks + " Ticks";
                if (config.showDistanceHUD())
                {
                    displayString += " | Dist: " + distance;
                }

                Point textPoint = npc.getCanvasTextLocation(graphics, displayString, npc.getLogicalHeight() + 30);
                if (textPoint != null)
                {
                    graphics.setFont(new Font("Arial", Font.BOLD, 12));
                    graphics.setColor(currentTicks <= 1 ? Color.RED : Color.YELLOW);
                    graphics.drawString(displayString, textPoint.getX(), textPoint.getY());
                }
            }
        }

        // LAYER 2: Milestone Quest Target Outlines
        if (config.trackQuestNPCs())
        {
            for (NPC npc : plugin.getQuestNpcs())
            {
                WorldPoint npcLoc = npc.getWorldLocation();
                if (npcLoc == null) continue;

                LocalPoint lp = LocalPoint.fromWorld(client, npcLoc);
                if (lp != null)
                {
                    java.awt.Polygon poly = Perspective.getCanvasTilePoly(client, lp);
                    if (poly != null)
                    {
                        graphics.setColor(config.questNpcColor());
                        graphics.fillPolygon(poly);
                    }
                }
            }
        }

        // LAYER 3: Translucent True-Tile Layer Rendering
        if (config.showTrueTile())
        {
            LocalPoint playerLocal = LocalPoint.fromWorld(client, playerLoc);
            if (playerLocal != null)
            {
                java.awt.Polygon playerPoly = Perspective.getCanvasTilePoly(client, playerLocal);
                if (playerPoly != null)
                {
                    graphics.setColor(isCurrentlySafe ? config.safeTileColor() : config.unsafeTileColor());
                    graphics.fillPolygon(playerPoly);
                    graphics.drawPolygon(playerPoly);
                }
            }
        }

        // LAYER 4: Dashboard Output Panels
        if (config.showLogoutPanel())
        {
            Font originalFont = graphics.getFont();
            float scalingFactor = config.panelFontSize() / 100f;
            Font scaledFont = originalFont.deriveFont(originalFont.getSize() * scalingFactor);
            graphics.setFont(scaledFont);

            panelComponent.getChildren().add(LineComponent.builder()
                .left("Security Profile:")
                .right(isCurrentlySafe ? "SAFE TO LOGOUT" : "IN THREAT BOUNDARY")
                .rightColor(isCurrentlySafe ? Color.GREEN : Color.RED)
                .build());

            Dimension dimensions = panelComponent.render(graphics);
            graphics.setFont(originalFont);
            return dimensions;
        }

        return null;
    }
}

package com.community.skillersafeground;

import com.google.inject.Provides;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
    name = "Skiller SafeGround",
    description = "A comprehensive visual security grid mapping all F2P hostile firewalls, universal overhead metronomes, and true tiles.",
    tags = {"skiller", "level3", "metronome", "safe", "overlay"},
    enabledByDefault = true
)
public class SkillerSafeGroundPlugin extends Plugin
{
    @Inject
    private Client client;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private SkillerSafeGroundOverlay overlay;

    @Inject
    private SkillerSafeGroundConfig config;

    private final Set<NPC> dangerousNpcs = new HashSet<>();
    private final Set<NPC> questNpcs = new HashSet<>();
    private final Map<NPC, Integer> npcMetronomeTimers = new HashMap<>();

    @Override
    protected void startUp() throws Exception
    {
        overlayManager.add(overlay);
        clearTrackingCache();
    }

    @Override
    protected void shutDown() throws Exception
    {
        overlayManager.remove(overlay);
        clearTrackingCache();
    }

    private void clearTrackingCache()
    {
        dangerousNpcs.clear();
        questNpcs.clear();
        npcMetronomeTimers.clear();
    }

    @Subscribe
    public void onNpcSpawned(NpcSpawned event)
    {
        NPC npc = event.getNpc();
        String name = npc.getName();
        if (name == null) return;

        boolean isThreat = false;

        // Comprehensive F2P Monster Array Sorting
        if ((name.equalsIgnoreCase("Dark wizard") || name.equalsIgnoreCase("Monk of zamorak")) && config.trackWizards()) isThreat = true;
        else if ((name.equalsIgnoreCase("Jail guard") || name.equalsIgnoreCase("Highwayman") || name.equalsIgnoreCase("Mugger")) && config.trackGuards()) isThreat = true;
        else if (name.toLowerCase().contains("scorpion") && config.trackScorpions()) isThreat = true;
        else if ((name.equalsIgnoreCase("Ice warrior") || name.equalsIgnoreCase("Ice giant")) && config.trackIceDungeon()) isThreat = true;
        else if ((name.equalsIgnoreCase("Hill giant") || name.equalsIgnoreCase("Moss giant") || name.equalsIgnoreCase("Deadly red spider")) && config.trackGiantsSpiders()) isThreat = true;
        else if ((name.equalsIgnoreCase("Minotaur") || name.equalsIgnoreCase("Flesh crawler") || name.equalsIgnoreCase("Catablepon") || name.equalsIgnoreCase("Ankou")) && config.trackStronghold()) isThreat = true;
        else if ((name.equalsIgnoreCase("Lesser demon") || name.equalsIgnoreCase("Bandit") || name.equalsIgnoreCase("Chaos dwarf") || name.equalsIgnoreCase("Grizzly bear") || name.equalsIgnoreCase("Ghost") || name.equalsIgnoreCase("Skeleton") || name.equalsIgnoreCase("Zombie") || name.equalsIgnoreCase("Hobgoblin")) && config.trackDeepWildy()) isThreat = true;
        else if (name.equalsIgnoreCase("Ancient guardian")) isThreat = true;

        if (isThreat)
        {
            dangerousNpcs.add(npc);
            npcMetronomeTimers.put(npc, getBaseAttackSpeed(name));
        }
        else if (config.trackQuestNPCs() && 
            (name.equalsIgnoreCase("Willow") || name.equalsIgnoreCase("Ramarno") || 
             name.equalsIgnoreCase("Checkal") || name.equalsIgnoreCase("Marley") || 
             name.equalsIgnoreCase("Aubury")))
        {
            questNpcs.add(npc);
        }
    }

    @Subscribe
    public void onNpcDespawned(NpcDespawned event)
    {
        NPC npc = event.getNpc();
        dangerousNpcs.remove(npc);
        questNpcs.remove(npc);
        npcMetronomeTimers.remove(npc);
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (!config.enableGlobalMetronome()) return;

        for (NPC npc : dangerousNpcs)
        {
            int currentTicks = npcMetronomeTimers.getOrDefault(npc, 4);
            currentTicks--;
            
            if (currentTicks <= 0)
            {
                currentTicks = getBaseAttackSpeed(npc.getName());
            }
            npcMetronomeTimers.put(npc, currentTicks);
        }
    }

    private int getBaseAttackSpeed(String npcName)
    {
        if (npcName == null) return 4;
        String lower = npcName.toLowerCase();
        
        // 5-Tick heavy weapon speeds
        if (lower.contains("giant") || lower.contains("wizard") || lower.contains("guardian") || lower.contains("guard") || lower.contains("catablepon")) return 5;
        // 4-Tick rapid melee weapon speeds (Scorpions, Spiders, Crawlers, Demons, Ankous)
        return 4;
    }

    public Set<NPC> getDangerousNpcs() { return dangerousNpcs; }
    public Set<NPC> getQuestNpcs() { return questNpcs; }
    public Map<NPC, Integer> getNpcMetronomeTimers() { return npcMetronomeTimers; }

    @Provides
    SkillerSafeGroundConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(SkillerSafeGroundConfig.class);
    }
}

